import { api, ApiError } from './api.js?v=6.9.0';
import { CONFIG } from './config.js?v=6.9.0';
import { icon } from './icons.js?v=6.9.0';

const app = document.querySelector('#app');
const portal = document.querySelector('#portal');
const prefsKey = `${CONFIG.preferencesKey}.platform`;
const state = {
  locale: localStorage.getItem(`${prefsKey}.locale`) || 'ar',
  theme: localStorage.getItem(`${prefsKey}.theme`) || 'dark',
  loading: true, admin: null, profile: null, companies: [], plans: [], audit: [], permissions: [], roleTemplates: [], roleTemplatePermissions: [], entitlements: [], planEntitlements: [], companyEntitlementOverrides: [], assetUrls: {},
  page: location.hash.replace('#/', '') || 'dashboard', search: '', status: 'all', selectedCompanyId: null, mobileNav: false,
  auditSearch: '', auditCompany: 'all', auditAction: 'all', auditFrom: '', auditTo: '', dataWarnings: [],
};
const L = (ar, en) => state.locale === 'ar' ? ar : en;
const e = (value = '') => String(value ?? '').replace(/[&<>'"]/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c]));
const asArray = (v) => Array.isArray(v) ? v : [];
const formatDate = (d) => d ? new Intl.DateTimeFormat(state.locale === 'ar' ? 'ar-EG' : 'en-GB', { dateStyle:'medium' }).format(new Date(d)) : '—';
const formatDateTime = (d) => d ? new Intl.DateTimeFormat(state.locale === 'ar' ? 'ar-EG' : 'en-GB', { dateStyle:'medium', timeStyle:'short' }).format(new Date(d)) : '—';
const formatBytes = (bytes=0) => { const n=Number(bytes||0); if(!n)return '0 B'; const u=['B','KB','MB','GB','TB']; const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),4); return `${(n/1024**i).toFixed(i?1:0)} ${u[i]}`; };
const money = (value, currency='EGP') => value === null || value === undefined || value === '' ? '—' : new Intl.NumberFormat(state.locale==='ar'?'ar-EG':'en-US',{style:'currency',currency:currency||'EGP',maximumFractionDigits:2}).format(Number(value));
const initials = (name='') => name.trim().split(/\s+/).slice(0,2).map((x)=>x[0]?.toUpperCase()).join('') || 'O';
const safeAssetPath=(path='')=>String(path||'').replace(/^\/+/, '');
const assetUrl=(path='')=>state.assetUrls[safeAssetPath(path)]||'';
const identityImage=(path,name,className='identity-avatar')=>assetUrl(path)?`<img class="${className}" src="${e(assetUrl(path))}" alt="${e(name||'')}" loading="lazy"/>`:`<span class="${className} identity-fallback">${e(initials(name))}</span>`;
const extensionForFile=(file)=>({'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/svg+xml':'svg'}[file?.type]||String(file?.name||'').split('.').pop()?.toLowerCase()||'bin');
async function uploadIdentityImage(file,pathBase){if(!file?.size)return null;if(!String(file.type||'').startsWith('image/'))throw new Error(L('اختر صورة صالحة','Choose a valid image'));if(file.size>5*1024*1024)throw new Error(L('حجم الصورة يجب ألا يتجاوز 5 ميجابايت','Image must not exceed 5 MB'));const path=`${pathBase}.${extensionForFile(file)}`;await api.uploadObject('identity-assets',path,file,{upsert:true});state.assetUrls[path]=await api.createSignedUrl('identity-assets',path,3600).catch(()=>'');return path;}
async function resolveIdentityAssets(paths=[]){const unique=[...new Set(paths.map(safeAssetPath).filter(Boolean))];await Promise.all(unique.map(async(path)=>{if(!state.assetUrls[path])state.assetUrls[path]=await api.createSignedUrl('identity-assets',path,3600).catch(()=>'');}));}
const permissionGroups=()=>state.permissions.reduce((acc,p)=>((acc[p.module]??=[]).push(p),acc),{});
const clientAppUrl = String(window.OPTIMUM_CLIENT_APP_URL || `${location.origin}${location.pathname.replace(/\/platform\/?$/,'/')}`);

function applyPreferences(){
  document.documentElement.lang=state.locale; document.documentElement.dir=state.locale==='ar'?'rtl':'ltr'; document.documentElement.dataset.theme=state.theme;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', state.theme==='dark'?'#07111f':'#f5f7fb');
}
applyPreferences();

function toast(type,title,message='',timeout=4500){
  let stack=document.querySelector('.toast-stack'); if(!stack){stack=document.createElement('div');stack.className='toast-stack';portal.append(stack);}
  const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<div class="toast-icon">${icon(type==='success'?'check':type==='error'?'close':'info',16)}</div><div class="toast-copy"><strong>${e(title)}</strong>${message?`<p>${e(message)}</p>`:''}</div><button class="icon-btn" data-close>${icon('close',15)}</button>`;
  stack.append(el);el.querySelector('[data-close]')?.addEventListener('click',()=>el.remove());setTimeout(()=>el.remove(),timeout);
}
function friendlyError(error){
  const source=error instanceof ApiError?error.message:(error?.message||L('حدث خطأ غير متوقع','An unexpected error occurred'));
  const raw=String(source||'').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  const map=[[/Invalid login credentials/i,L('البريد أو كلمة المرور غير صحيحة. استخدم كلمة المرور الحالية التي ثبّتها الحساب، وليس كلمة المرور المؤقتة القديمة.','Email or password is incorrect. Use the account’s current password, not an old temporary password.')],[/Invalid or expired session|Session expired|refresh token|JWT expired|Authentication required/i,L('انتهت جلسة لوحة الإدارة. سجّل الدخول مرة أخرى؛ جلسة تطبيق الشركة منفصلة ولن تتأثر.','The platform session expired. Sign in again; the client application session is isolated and will not be affected.')],[/Platform administrator/i,L('هذه اللوحة متاحة لمسؤولي Optimum فقط.','This console is restricted to Optimum platform administrators.')],[/duplicate key|already exists/i,L('هذه البيانات مستخدمة بالفعل. راجع البريد أو رابط الشركة.','These details are already in use. Check the email or company slug.')],[/Invalid email/i,L('راجع عنوان البريد الإلكتروني.','Check the email address.')],[/Temporary password expired/i,L('انتهت صلاحية كلمة المرور المؤقتة. أنشئ واحدة جديدة.','The temporary password has expired. Generate a new one.')],[/Unknown action|Unsupported action/i,L('خدمة الحسابات لا تطابق نسخة الواجهة. أعد تشغيل النسخة الجديدة واضغط Ctrl + F5.','The account service does not match this interface. Restart the fixed version and press Ctrl + F5.')],[/Select at least one permission/i,L('اختر صلاحية واحدة على الأقل قبل الحفظ.','Select at least one permission before saving.')],[/400 Bad Request/i,L('رفض الخادم الطلب. راجع الحقول المطلوبة وحاول مرة أخرى.','The server rejected the request. Check required fields and try again.')]];
  return map.find(([re])=>re.test(raw))?.[1]||raw;
}
function setBusy(form,busy){if(form)form.dataset.busy=busy?'true':'false';form?.querySelectorAll('button').forEach((x)=>x.disabled=busy);const btn=form?.querySelector('[type="submit"]');if(btn){if(busy){btn.dataset.old=btn.innerHTML;btn.innerHTML=`<span class="spinner"></span>${L('جارٍ التنفيذ...','Working...')}`;}else if(btn.dataset.old){btn.innerHTML=btn.dataset.old;delete btn.dataset.old;}}}
function formObject(form){const out={};for(const [k,v] of new FormData(form).entries())out[k]=v;return out;}
function openDialog({title,subtitle='',body,large=false,wide=false}){portal.innerHTML=`<div class="overlay" data-dismiss><section class="dialog ${large?'dialog-lg':''} ${wide?'modal-xl':''}" role="dialog" data-dialog><header class="dialog-head"><div class="dialog-head-copy"><h3>${e(title)}</h3>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="icon-btn" data-dismiss>${icon('close',18)}</button></header><div class="dialog-body">${body}</div></section></div>`;}
function closeDialog(){portal.innerHTML='';}
function statusBadge(status){const labels={trial:L('تجريبي','Trial'),active:L('نشط','Active'),suspended:L('موقوف','Suspended'),expired:L('منتهي','Expired'),pending:L('بانتظار الدفع','Pending'),paid:L('مدفوع','Paid'),overdue:L('متأخر','Overdue'),waived:L('معفى','Waived')};const cls={active:'badge-success',paid:'badge-success',trial:'badge-warning',pending:'badge-warning',overdue:'badge-danger',waived:'badge-info',suspended:'badge-danger',expired:'badge-danger'}[status]||'';return `<span class="badge ${cls}">${e(labels[status]||status||'—')}</span>`;}
function slugify(value=''){return value.trim().toLowerCase().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'');}
function toLocalInput(value){if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}

async function boot(){
  state.loading=true;render();
  if(!api.user){state.loading=false;render();return;}
  try{
    const userId=api.user.id;
    const [admins,profiles,security]=await Promise.all([
      api.select('platform_admins',{filters:{user_id:`eq.${userId}`,is_active:'eq.true'}}),
      api.select('profiles',{filters:{id:`eq.${userId}`}}),
      api.select('account_security',{filters:{user_id:`eq.${userId}`}}),
    ]);
    state.admin=admins[0]||null;state.profile=profiles[0]||null;
    if(security[0]?.must_change_password){location.href=`${clientAppUrl.replace(/#.*$/,'').replace(/\/$/,'')}/#/dashboard`;return;}
    if(state.admin)await loadData();
  }catch(error){toast('error',L('تعذر تحميل لوحة المنصة','Could not load platform console'),friendlyError(error),7000);}
  state.loading=false;render();
}
async function loadCompanyDirectory(){
  try { return await api.rpc('platform_company_directory'); }
  catch (error) {
    const message=String(error?.message||'');
    if (/schema cache|function .* does not exist|PGRST202/i.test(message)) return api.rpc('platform_company_overview');
    throw error;
  }
}
async function loadData(){
  const warnings=[];const safe=(key,promise,fallback=[])=>promise.catch((error)=>{warnings.push({key,message:friendlyError(error)});console.warn(`[Platform] ${key} failed`,error);return fallback;});
  const [companies,plans,audit,permissions,roleTemplates,roleTemplatePermissions,entitlements,planEntitlements,companyEntitlementOverrides]=await Promise.all([
    loadCompanyDirectory(),
    api.select('service_plans',{filters:{is_active:'eq.true'},order:'sort_order.asc'}),
    safe('platform_audit',api.select('platform_audit_events',{order:'created_at.desc',limit:250})),
    safe('permissions',api.select('permissions',{order:'module.asc,key.asc'})),
    safe('role_templates',api.select('role_templates',{order:'sort_order.asc,created_at.asc'})),
    safe('role_template_permissions',api.select('role_template_permissions',{order:'permission_key.asc'})),
    safe('entitlements',api.select('entitlements',{order:'module.asc,sort_order.asc,key.asc'})),
    safe('plan_entitlements',api.select('service_plan_entitlements',{order:'plan_id.asc,entitlement_key.asc'})),
    safe('company_entitlement_overrides',api.select('company_entitlement_overrides',{order:'company_id.asc,entitlement_key.asc'})),
  ]);
  state.companies=asArray(companies);state.plans=plans;state.audit=audit;state.permissions=permissions;state.roleTemplates=roleTemplates;state.roleTemplatePermissions=roleTemplatePermissions;state.entitlements=entitlements;state.planEntitlements=planEntitlements;state.companyEntitlementOverrides=companyEntitlementOverrides;state.dataWarnings=warnings;
  await resolveIdentityAssets(state.companies.map((c)=>c.branding_logo_path));
}

