async function companyDetailsDialog(id){const c=state.companies.find((x)=>x.company_id===id);if(!c)return;openDialog({title:c.company_name,subtitle:L('جارٍ تحميل بيانات الحسابات...','Loading account directory...'),large:true,wide:true,body:`<div class="platform-loading-inline"><span class="spinner"></span></div>`});try{const [membersRaw,healthRaw]=await Promise.all([api.rpc('platform_member_directory',{p_company_id:id}),api.rpc('organization_health_snapshot',{p_company_id:id}).catch(()=>null)]);const members=asArray(membersRaw),health=healthRaw||null;await resolveIdentityAssets([c.branding_logo_path,...members.map((m)=>m.avatar_path)]);const healthIssues=asArray(health?.issues);const healthPanel=health?`<section class="platform-org-health"><div class="platform-health-score" style="--score:${Number(health.score||0)}"><strong>${Number(health.score||0)}%</strong><span>${L('جاهزية المؤسسة','Organization readiness')}</span></div><div><div class="section-head"><div><h3>${L('صحة المؤسسة','Organization health')}</h3><p>${healthIssues.length?L('مشكلات تحتاج متابعة قبل الاعتماد الكامل.','Issues to review before full readiness.'):L('لا توجد مشكلات تنظيمية حرجة حاليًا.','No critical organization issues detected.')}</p></div></div><div class="platform-health-issues">${healthIssues.slice(0,4).map((x)=>`<article class="${e(x.severity||'info')}"><span>${icon(x.severity==='danger'?'alert':'info',14)}</span><div><strong>${e(state.locale==='ar'?(x.title_ar||x.title_en):(x.title_en||x.title_ar))}</strong><small>${e(state.locale==='ar'?(x.detail_ar||x.detail_en):(x.detail_en||x.detail_ar))}</small></div>${Number(x.count)>0?`<b>${Number(x.count)}</b>`:''}</article>`).join('')||`<span class="badge badge-success">${L('سليم','Healthy')}</span>`}</div></div></section>`:'';portal.querySelector('.dialog-body').innerHTML=`${healthPanel}<div class="company-detail-hero">${identityImage(c.branding_logo_path,c.company_name,'company-detail-logo')}<div><h3>${e(c.branding_app_name||c.company_name)}</h3><p>${e(c.official_email||c.primary_contact_email||'—')} · ${e(c.city||'—')}</p></div><div class="company-detail-status">${statusBadge(c.status)}${statusBadge(c.payment_status)}</div></div><div class="company-detail-metrics"><article><span>${L('الخطة','Plan')}</span><strong>${e(state.locale==='ar'?c.plan_name_ar:c.plan_name_en)}</strong></article><article><span>${L('الأعضاء','Members')}</span><strong>${c.member_count} / ${c.max_members}</strong></article><article><span>${L('المشاريع','Projects')}</span><strong>${c.project_count} / ${c.max_projects}</strong></article><article><span>${L('التخزين','Storage')}</span><strong>${formatBytes(c.storage_bytes)} / ${formatBytes(c.max_storage_bytes)}</strong></article></div><div class="section-head" style="margin-top:22px"><div><h3>${L('حسابات الشركة','Company accounts')}</h3><p>${L('الصورة والوظيفة والراتب وحالة التفعيل في دليل إداري واحد.','Photo, job, compensation, and activation status in one administrative directory.')}</p></div><span class="spacer"></span><button class="btn btn-secondary btn-sm" data-action="company-branding" data-id="${c.company_id}">${icon('palette',14)} ${L('الهوية والألوان','Identity & colors')}</button><button class="btn btn-secondary btn-sm" data-action="edit-company" data-id="${c.company_id}">${icon('edit',14)} ${L('تعديل الشركة','Edit company')}</button></div><div class="table-wrap"><table><thead><tr><th>${L('المستخدم','User')}</th><th>${L('الوظيفة','Job')}</th><th>${L('الدور','Role')}</th><th>${L('الراتب','Salary')}</th><th>${L('حالة الحساب','Account')}</th><th>${L('آخر تفعيل','Activation')}</th><th></th></tr></thead><tbody>${members.map((m)=>`<tr><td><div class="entity">${identityImage(m.avatar_path,m.full_name||m.email,'member-table-avatar')}<div class="entity-copy"><strong>${e(m.full_name||'—')}</strong><span>${e(m.email||'—')}</span></div></div></td><td><strong>${e(m.job_title||'—')}</strong><div class="table-subtext">${e(m.department||m.employee_code||'')}</div></td><td>${e(state.locale==='ar'?m.role_name_ar:m.role_name_en)}</td><td><strong>${e(money(m.salary_amount,m.currency||'EGP'))}</strong><div class="table-subtext">${e(m.pay_frequency||'—')}</div></td><td>${m.must_change_password?`<span class="badge badge-warning">${L('بانتظار تغيير الباسورد','Pending first login')}</span>`:`<span class="badge badge-success">${L('مفعّل','Activated')}</span>`}</td><td>${formatDateTime(m.first_login_completed_at||m.joined_at)}</td><td><button class="btn btn-secondary btn-sm" data-action="reset-member-password" data-membership-id="${m.membership_id}" data-email="${e(m.email||'')}">${icon('refresh',14)} ${L('باسورد مؤقت جديد','New temp password')}</button></td></tr>`).join('')}</tbody></table></div>`;}catch(error){portal.querySelector('.dialog-body').innerHTML=`<div class="alert alert-danger">${icon('alert',18)}<div class="alert-copy"><strong>${L('تعذر تحميل الحسابات','Could not load accounts')}</strong><p>${e(friendlyError(error))}</p></div></div>`;}}
function credentialsDialog(result,context='company'){const existing=Boolean(result.existing_account),password=result.temporary_password;openDialog({title:L('تم الإنشاء بنجاح','Provisioning complete'),subtitle:existing?L('الحساب كان موجودًا وتم ربطه بالشركة.','The existing account was linked to the company.'):L('احفظ بيانات الدخول قبل إغلاق النافذة.','Save the credentials before closing this window.'),large:true,body:`<div class="credential-success"><span class="credential-success-icon">${icon('check',30)}</span><h3>${context==='company'?L('الشركة وحساب المالك جاهزان','Company and owner account are ready'):L('الحساب جاهز','Account is ready')}</h3><p>${existing?L('لن نغيّر كلمة مرور حساب موجود. يستخدم المستخدم كلمة مروره الحالية.','An existing account keeps its current password.'):L('كلمة المرور المؤقتة تظهر هنا مرة واحدة فقط.','The temporary password is shown here only once.')}</p></div><div class="credential-grid"><div class="credential-field"><span>${L('البريد','Email')}</span><code class="credential-value" dir="ltr">${e(result.email||'—')}</code><button class="icon-btn" data-copy="${e(result.email||'')}">${icon('copy',15)}</button></div><div class="credential-field"><span>${L('كلمة المرور المؤقتة','Temporary password')}</span><code class="credential-value credential-password" dir="ltr">${e(password||L('الحساب موجود — استخدم الباسورد الحالي','Existing account — use current password'))}</code>${password?`<button class="icon-btn" data-copy="${e(password)}">${icon('copy',15)}</button>`:''}</div><div class="credential-field"><span>${L('تنتهي في','Expires')}</span><code class="credential-value" dir="ltr">${formatDateTime(result.temporary_password_expires_at)}</code></div><div class="credential-field"><span>${L('إرسال البريد','Email delivery')}</span><code class="credential-value" dir="ltr">${e(result.email_delivery||'not_configured')}</code></div><div class="credential-field"><span>${L('التحقق','Verification')}</span><code class="credential-value ${result.credential_verified===false?'credential-unverified':'credential-verified'}" dir="ltr">${result.credential_verified===false?L('فشل','Failed'):L('تم اختبار بيانات الدخول','Credentials verified')}</code></div></div>${result.setup_warning?`<div class="alert alert-warning">${icon('alert',18)}<div class="alert-copy"><strong>${L('الشركة والحساب تم إنشاؤهما','Company and account were created')}</strong><p>${e(result.setup_warning)}</p></div></div>`:''}<div class="alert alert-warning">${icon('alert',18)}<div class="alert-copy"><strong>${L('مهم','Important')}</strong><p>${L('أرسل بيانات الدخول عبر قناة آمنة. سيُجبر المستخدم على تغيير الباسورد فور أول دخول.','Send credentials through a secure channel. The user must change the password immediately on first login.')}</p></div></div><div class="inline-actions credential-actions"><button class="btn btn-secondary" data-copy-credentials data-email="${e(result.email||'')}" data-password="${e(password||'')}">${icon('copy',15)} ${L('نسخ بيانات الدخول','Copy credentials')}</button><a class="btn btn-primary" href="mailto:${e(result.email||'')}?subject=Optimum%20account&body=${encodeURIComponent(`Your Optimum account is ready.\nLogin: ${clientAppUrl}\nEmail: ${result.email||''}\n${password?`Temporary password: ${password}\n`:''}You must change the password on first login.`)}">${icon('mail',15)} ${L('فتح رسالة بريد','Open email')}</a></div>`});}

function platformBrandingDialog(c){openDialog({title:L('هوية الشركة ومظهر التطبيق','Company identity & application appearance'),subtitle:L('يمكن لصاحب الشركة تعديل نفس الإعدادات من داخل التطبيق حسب الصلاحية.','The company owner can manage the same settings inside the client application when permitted.'),large:true,body:`<form class="form-grid" data-form="platform-branding" data-company-id="${c.company_id}"><label class="image-upload-card">${identityImage(c.branding_logo_path,c.company_name,'image-upload-preview')}<span><strong>${L('شعار الشركة','Company logo')}</strong><small>${L('صورة مربعة واضحة — حتى 5MB','Clear square image — up to 5 MB')}</small></span><input type="file" name="logo_file" accept="image/png,image/jpeg,image/webp,image/svg+xml" /></label><div class="form-grid cols-2"><div class="form-row"><label>${L('اسم التطبيق','Application name')}</label><input class="input" name="app_name" value="${e(c.branding_app_name||c.company_name)}" /></div><div class="form-row"><label>${L('السطر التعريفي','Tagline')}</label><input class="input" name="tagline" value="${e(c.branding_tagline||'')}" /></div><div class="form-row"><label>${L('اللون الأساسي','Primary color')}</label><input class="input color-input" name="primary_color" type="color" value="${e(c.branding_primary_color||'#4f46e5')}" /></div><div class="form-row"><label>${L('لون التمييز','Accent color')}</label><input class="input color-input" name="accent_color" type="color" value="${e(c.branding_accent_color||'#14b8a6')}" /></div><div class="form-row"><label>${L('الثيم الافتراضي','Default theme')}</label><select class="select" name="default_theme">${['system','light','dark'].map((x)=>`<option value="${x}" ${(c.branding_default_theme||'system')===x?'selected':''}>${e(x)}</option>`).join('')}</select></div><div class="form-row"><label>${L('شكل القائمة','Sidebar style')}</label><select class="select" name="sidebar_style">${['glass','solid','gradient'].map((x)=>`<option value="${x}">${e(x)}</option>`).join('')}</select></div></div><button class="btn btn-primary" type="submit">${icon('save',16)} ${L('حفظ الهوية','Save identity')}</button></form>`});}
function templatePermissionKeys(templateId){return state.roleTemplatePermissions.filter((x)=>x.template_id===templateId&&x.allowed).map((x)=>x.permission_key);}
function companyEntitlementsDialog(companyId){if(hasPlatformWarning('entitlements','plan_entitlements','company_entitlement_overrides')){toast('error',L('بيانات الميزات غير مكتملة','Entitlement data is incomplete'),L('أعد التحميل قبل تعديل ميزات الشركة حتى لا تعتمد على حالة ناقصة.','Reload before changing company entitlements so you do not act on partial data.'));return;}const c=state.companies.find(x=>x.company_id===companyId),planId=c?.plan_id;const rows=state.entitlements.map(ent=>{const plan=state.planEntitlements.find(x=>x.plan_id===planId&&x.entitlement_key===ent.key),override=state.companyEntitlementOverrides.find(x=>x.company_id===companyId&&x.entitlement_key===ent.key),enabled=override?override.enabled!==false:Boolean(plan?.enabled),linkedPermissions=state.permissions.filter((p)=>p.entitlement_key===ent.key),isModule=ent.key.startsWith('module.'),source=override?L('تخصيص للشركة','Company override'):plan?L('موروث من الباقة','Inherited from plan'):L('غير مهيأة في الباقة','Not configured in plan');return `<article class="platform-entitlement-row policy-impact-row ${enabled?'enabled':'disabled'}"><div><strong>${e(state.locale==='ar'?ent.name_ar||ent.key:ent.name_en||ent.key)}</strong><small>${e(ent.key)} · ${e(ent.module||'general')} · ${source}</small><p>${isModule?L(`تتحكم في ظهور الوحدة ومساراتها، وتغلق ${linkedPermissions.length} صلاحية مرتبطة بها عند الإيقاف.`,`Controls module surfaces and routes; disabling it closes ${linkedPermissions.length} linked permission(s).`):linkedPermissions.length?L(`${linkedPermissions.length} صلاحية مرتبطة بهذه الميزة.`,`${linkedPermissions.length} permission(s) are linked to this feature.`):L('ميزة مستقلة تُطبق على الإجراءات المرتبطة بها مباشرة.','Standalone feature enforced on its related actions directly.')}</p></div><span class="badge ${enabled?'badge-success':'badge-danger'}">${enabled?L('مفعلة','Enabled'):L('متوقفة','Disabled')}</span><div class="inline-actions"><button class="btn btn-sm ${enabled?'btn-ghost danger':'btn-primary'}" data-action="company-entitlement-set" data-company-id="${companyId}" data-key="${e(ent.key)}" data-name="${e(state.locale==='ar'?ent.name_ar||ent.key:ent.name_en||ent.key)}" data-module="${isModule?'true':'false'}" data-enabled="${enabled?'false':'true'}">${enabled?L('إيقاف','Disable'):L('تفعيل','Enable')}</button>${override?`<button class="btn btn-secondary btn-sm" data-action="company-entitlement-clear" data-company-id="${companyId}" data-key="${e(ent.key)}">${L('استخدام الباقة','Use plan')}</button>`:''}</div></article>`;}).join('');const usage=`<div class="platform-policy-summary"><article><span>${icon('users',16)}</span><div><strong>${Number(c?.member_count||0)} / ${Number(c?.max_members||0)||'∞'}</strong><small>${L('الأعضاء','Members')}</small></div></article><article><span>${icon('briefcase',16)}</span><div><strong>${Number(c?.project_count||0)} / ${Number(c?.max_projects||0)||'∞'}</strong><small>${L('المشاريع','Projects')}</small></div></article><article><span>${icon('layers',16)}</span><div><strong>${state.entitlements.filter((ent)=>{const o=state.companyEntitlementOverrides.find(x=>x.company_id===companyId&&x.entitlement_key===ent.key),p=state.planEntitlements.find(x=>x.plan_id===planId&&x.entitlement_key===ent.key);return o?o.enabled!==false:Boolean(p?.enabled)}).length}/${state.entitlements.length}</strong><small>${L('ميزات فعالة','Effective features')}</small></div></article></div>`;openDialog({title:L('ميزات الشركة وحدود الباقة','Company entitlements & plan access'),subtitle:c?.company_name||'',large:true,wide:true,body:`${usage}<div class="platform-policy-note">${icon('shield',18)}<div><strong>${L('هذه الإعدادات تشكل واجهة الشركة فعليًا','These settings actively shape the company UI')}</strong><p>${L('تعطيل وحدة يخفيها من التنقل والبحث والإجراءات ويجعل صلاحياتها غير فعالة على الخادم.','Disabling a module removes it from navigation, search, and actions, while its permissions become ineffective on the server.')}</p></div></div><div class="platform-entitlement-grid">${rows||`<p>${L('لا توجد ميزات معرفة.','No entitlements configured.')}</p>`}</div>`});}
async function setCompanyEntitlementFromButton(target){if(hasPlatformWarning('entitlements','plan_entitlements','company_entitlement_overrides'))throw new Error(L('أعد تحميل بيانات الميزات أولًا.','Reload entitlement data first.'));const enabled=target.dataset.enabled==='true';const execute=async()=>{await api.rpc('set_company_entitlement_override',{p_company_id:target.dataset.companyId,p_entitlement_key:target.dataset.key,p_enabled:enabled,p_limits:{},p_reason:L('تخصيص من لوحة المنصة','Platform console override')});await loadData();companyEntitlementsDialog(target.dataset.companyId);};if(enabled){await execute();return;}openDialog({title:L('تأكيد إيقاف الميزة','Confirm feature disable'),subtitle:target.dataset.name||target.dataset.key,body:`<div class="platform-policy-note danger">${icon('alert',18)}<div><strong>${L('سيُطبق الإيقاف على تجربة الشركة وصلاحياتها الفعلية.','The disable will affect the company experience and effective access.')}</strong><p>${target.dataset.module==='true'?L('ستختفي الوحدة من التنقل والبحث والإجراءات، ولن تستطيع الصلاحيات المرتبطة بها تجاوز الإيقاف.','The module will disappear from navigation, search, and actions; linked permissions cannot bypass the disable.'):L('ستتوقف العمليات المرتبطة بهذه الميزة حتى إعادة تفعيلها.','Operations tied to this feature will be blocked until it is enabled again.')}</p></div></div>`,footer:`<button class="btn btn-secondary" data-action="close-overlay">${L('إلغاء','Cancel')}</button><button class="btn btn-danger" id="confirm-entitlement-disable">${L('إيقاف الميزة','Disable feature')}</button>`});document.querySelector('#confirm-entitlement-disable')?.addEventListener('click',async()=>{closeOverlay();try{await execute();}catch(error){toast('error',L('تعذر تحديث الميزة','Could not update feature'),error.message||String(error));}});}
function roleTemplatesView(){const groups=permissionGroups();return `<div class="page-head"><div><span class="eyebrow">${L('قوالب أدوار المنصة','PLATFORM ROLE BLUEPRINTS')}</span><h2>${L('مكتبة الأدوار العالمية','Global role library')}</h2><p>${L('أنشئ قوالب احترافية تظهر لكل شركة كنقطة بداية، بينما تظل كل شركة قادرة على تعديل أدوارها الخاصة.','Create professional templates available to every company, while each company remains free to customize its own roles.')}</p></div><button class="btn btn-primary btn-lg" data-action="new-role-template">${icon('plus',17)} ${L('قالب دور جديد','New role template')}</button></div><div class="role-library-summary grid grid-4"><article class="card mini-stat"><strong>${state.roleTemplates.length}</strong><span>${L('إجمالي القوالب','Total templates')}</span></article><article class="card mini-stat"><strong>${state.roleTemplates.filter((x)=>x.is_active).length}</strong><span>${L('نشطة','Active')}</span></article><article class="card mini-stat"><strong>${state.roleTemplates.filter((x)=>x.is_recommended).length}</strong><span>${L('موصى بها','Recommended')}</span></article><article class="card mini-stat"><strong>${Object.keys(groups).length}</strong><span>${L('وحدات صلاحيات','Permission modules')}</span></article></div><section class="role-template-grid platform-role-template-grid">${state.roleTemplates.map((tpl)=>{const count=templatePermissionKeys(tpl.id).length;return `<article class="role-template-card platform-template-card" style="--role-color:${e(tpl.color||'#4f46e5')}"><div class="role-template-card-top"><span class="role-template-icon">${icon(tpl.icon||'shield',19)}</span><div class="inline-actions">${tpl.is_recommended?`<span class="badge badge-success">${L('موصى به','Recommended')}</span>`:''}${tpl.is_active?`<span class="badge">${L('نشط','Active')}</span>`:`<span class="badge badge-danger">${L('متوقف','Inactive')}</span>`}</div></div><div><span class="eyebrow">${e(tpl.category||'general')}</span><h3>${e(state.locale==='ar'?tpl.name_ar:tpl.name_en)}</h3><p>${e((state.locale==='ar'?tpl.description_ar:tpl.description_en)||'')}</p></div>${count===0?`<div class="permission-empty-warning">${icon('alert',13)} ${L('هذا القالب يحتاج إعادة حفظ الصلاحيات.','This template needs its permissions saved again.')}</div>`:''}<div class="role-template-card-footer"><span>${icon('shield',14)} ${count} ${L('صلاحية','permissions')}</span><div class="inline-actions"><button class="icon-btn" data-action="edit-role-template" data-id="${tpl.id}">${icon('edit',15)}</button><button class="icon-btn danger" data-action="delete-role-template" data-id="${tpl.id}">${icon('trash',15)}</button></div></div></article>`;}).join('')||`<div class="empty"><div><div class="empty-icon">${icon('shield',22)}</div><h3>${L('لا توجد قوالب بعد','No templates yet')}</h3></div></div>`}</section>`;}
function selectedTemplatePermissionKeys(form){return [...form.querySelectorAll('input[name="permission"]:checked')].map((x)=>x.value).filter(Boolean);}
function updateTemplatePermissionUi(form){if(!form)return;const selected=selectedTemplatePermissionKeys(form);const count=form.querySelector('[data-template-count]');if(count)count.textContent=`${selected.length} ${L('صلاحية محددة','permissions selected')}`;form.querySelectorAll('[data-template-module]').forEach((toggle)=>{const items=[...form.querySelectorAll(`input[name="permission"][data-module="${CSS.escape(toggle.dataset.templateModule)}"]`)];const checked=items.filter((x)=>x.checked).length;toggle.checked=items.length>0&&checked===items.length;toggle.indeterminate=checked>0&&checked<items.length;});}
function roleTemplateDialog(template=null){if(hasPlatformWarning('permissions','role_templates','role_template_permissions')){toast('error',L('مكتبة الصلاحيات غير مكتملة','Permission library is incomplete'),L('أعد التحميل قبل تعديل قوالب الأدوار.','Reload before editing role templates.'));return;}const enabled=new Set(template?templatePermissionKeys(template.id):[]),groups=permissionGroups();openDialog({title:template?L('تعديل قالب الدور','Edit role template'):L('إنشاء قالب دور','Create role template'),subtitle:L('القالب لا يفرض صلاحيات على الشركات؛ هو نقطة بداية ذكية وسهلة.','A template never forces permissions on companies; it is a smart starting point.'),large:true,wide:true,body:`<form class="role-editor-form" data-form="role-template" data-template-id="${template?.id||''}"><div class="role-identity-panel"><div class="role-color-preview" style="--role-color:${e(template?.color||'#4f46e5')}">${icon(template?.icon||'shield',22)}</div><div class="form-grid cols-3"><div class="form-row"><label>${L('الكود الداخلي','Internal code')}</label><input class="input" name="code" value="${e(template?.code||'')}" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" required /></div><div class="form-row"><label>${L('الاسم بالعربي','Arabic name')}</label><input class="input" name="name_ar" value="${e(template?.name_ar||'')}" required /></div><div class="form-row"><label>${L('الاسم بالإنجليزي','English name')}</label><input class="input" name="name_en" value="${e(template?.name_en||'')}" required /></div><div class="form-row"><label>${L('التصنيف','Category')}</label><select class="select" name="category">${['leadership','management','engineering','operations','finance','hr','viewer','general'].map((x)=>`<option value="${x}" ${template?.category===x?'selected':''}>${e(x)}</option>`).join('')}</select></div><div class="form-row"><label>${L('اللون','Color')}</label><input class="input color-input" name="color" type="color" value="${e(template?.color||'#4f46e5')}" /></div><div class="form-row"><label>${L('الأيقونة','Icon')}</label><select class="select" name="icon">${['shield','briefcase','users','eye','activity','building','settings'].map((x)=>`<option value="${x}" ${template?.icon===x?'selected':''}>${e(x)}</option>`).join('')}</select></div><div class="form-row"><label>${L('الوصف بالعربي','Arabic description')}</label><input class="input" name="description_ar" value="${e(template?.description_ar||'')}" /></div><div class="form-row"><label>${L('الوصف بالإنجليزي','English description')}</label><input class="input" name="description_en" value="${e(template?.description_en||'')}" /></div><div class="form-row role-flags"><label><input type="checkbox" name="is_active" ${template?.is_active!==false?'checked':''}/> ${L('نشط','Active')}</label><label><input type="checkbox" name="is_recommended" ${template?.is_recommended?'checked':''}/> ${L('موصى به','Recommended')}</label></div></div></div><div class="permission-editor-head"><div><h3>${L('مصفوفة الصلاحيات','Permission matrix')}</h3><p>${L('اختر أقل صلاحيات لازمة للدور.','Choose the minimum permissions required by the role.')}</p></div><div class="inline-actions"><button class="btn btn-ghost btn-sm" type="button" data-action="template-select-all">${L('تحديد الكل','Select all')}</button><button class="btn btn-ghost btn-sm" type="button" data-action="template-clear-all">${L('إلغاء الكل','Clear all')}</button></div></div><div class="permission-groups permission-groups-smart">${Object.entries(groups).map(([module,items])=>`<section class="permission-group"><header><h4>${e(module)}</h4><label class="module-toggle"><input type="checkbox" data-template-module="${e(module)}" ${items.every((p)=>enabled.has(p.key))?'checked':''}/><span>${L('الوحدة كاملة','Full module')}</span></label></header>${items.map((p)=>`<label class="permission-row"><span class="permission-copy"><strong>${e(state.locale==='ar'?p.description_ar:p.description_en)}</strong><span>${e(p.key)}</span></span><span class="switch"><input type="checkbox" name="permission" data-module="${e(module)}" value="${e(p.key)}" ${enabled.has(p.key)?'checked':''}/><span class="switch-track"></span></span></label>`).join('')}</section>`).join('')}</div><div class="modal-sticky-actions"><span data-template-count>${enabled.size} ${L('صلاحية محددة','permissions selected')}</span><button class="btn btn-primary" type="submit">${icon('save',16)} ${L('حفظ القالب','Save template')}</button></div></form>`});}
function render(){
  if(state.loading){app.innerHTML=loadingView();return;}
  if(!api.user){app.innerHTML=loginView();return;}
  if(!state.admin){app.innerHTML=deniedView();return;}
  const content=state.page==='companies'?companiesView():state.page==='role-templates'?roleTemplatesView():state.page==='audit'?auditView():dashboardView();app.innerHTML=shell(content);
}

app.addEventListener('click',async(event)=>{
  const nav=event.target.closest('[data-nav]');if(nav){state.page=nav.dataset.nav;state.mobileNav=false;location.hash=`#/${state.page}`;render();return;}
  const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
  try{
    if(action==='menu'){state.mobileNav=!state.mobileNav;render();}
    else if(action==='locale'){state.locale=state.locale==='ar'?'en':'ar';localStorage.setItem(`${prefsKey}.locale`,state.locale);applyPreferences();render();}
    else if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem(`${prefsKey}.theme`,state.theme);applyPreferences();render();}
    else if(action==='sign-out'){state.mobileNav=false;await api.signOut();state.admin=null;render();}
    else if(action==='refresh'){state.loading=true;render();await loadData();state.loading=false;render();toast('success',L('تم تحديث البيانات','Data refreshed'));}
    else if(action==='create-company')createCompanyDialog();
    else if(action==='new-role-template')roleTemplateDialog();
    else if(action==='edit-role-template')roleTemplateDialog(state.roleTemplates.find((x)=>x.id===target.dataset.id));
    else if(action==='delete-role-template'){if(confirm(L('حذف قالب الدور؟ لن تتأثر الأدوار التي أنشأتها الشركات سابقًا.','Delete this role template? Existing company roles will not be affected.'))){await api.rpc('platform_delete_role_template',{p_template_id:target.dataset.id});await loadData();render();toast('success',L('تم حذف القالب','Template deleted'));}}
    else if(action==='company-details')await companyDetailsDialog(target.dataset.id);
    else if(action==='company-branding'){const c=state.companies.find((x)=>x.company_id===target.dataset.id);if(c)platformBrandingDialog(c);}
    else if(action==='company-entitlements'){companyEntitlementsDialog(target.dataset.id);}
    else if(action==='company-entitlement-set'){await setCompanyEntitlementFromButton(target);}
    else if(action==='company-entitlement-clear'){if(hasPlatformWarning('entitlements','plan_entitlements','company_entitlement_overrides'))throw new Error(L('أعد تحميل بيانات الميزات أولًا.','Reload entitlement data first.'));await api.rpc('clear_company_entitlement_override',{p_company_id:target.dataset.companyId,p_entitlement_key:target.dataset.key});await loadData();companyEntitlementsDialog(target.dataset.companyId);}
    else if(action==='edit-company'){const c=state.companies.find((x)=>x.company_id===target.dataset.id);if(c)companyEditDialog(c);}
    else if(action==='reset-member-password'){const result=await api.invokeFunction('identity-provisioning-v55',{action:'reset_temporary_password',membership_id:target.dataset.membershipId,password_hours:48});credentialsDialog(result,'member');await loadData();}
    else if(action==='audit-details'){const row=state.audit.find((x)=>String(x.id)===String(target.dataset.id));if(row)platformAuditDetails(row);}
    else if(action==='audit-clear'){state.auditSearch='';state.auditCompany='all';state.auditAction='all';state.auditFrom='';state.auditTo='';render();}
    else if(action==='audit-export'){exportPlatformAudit(filteredPlatformAudit());toast('success',L('تم تجهيز ملف السجل','Audit file exported'));}
  }catch(error){toast('error',L('تعذر تنفيذ العملية','Action failed'),friendlyError(error),7000);}
});
portal.addEventListener('click',async(event)=>{
  if(event.target.matches('.overlay[data-dismiss]')||event.target.closest('button[data-dismiss]')){closeDialog();return;}
  const copy=event.target.closest('[data-copy]');if(copy){await navigator.clipboard.writeText(copy.dataset.copy);toast('success',L('تم النسخ','Copied'));return;}
  const credentials=event.target.closest('[data-copy-credentials]');if(credentials){await navigator.clipboard.writeText(`${L('البريد','Email')}: ${credentials.dataset.email}\n${L('كلمة المرور المؤقتة','Temporary password')}: ${credentials.dataset.password}\n${L('رابط الدخول','Login')}: ${clientAppUrl}`);toast('success',L('تم نسخ بيانات الدخول','Credentials copied'));return;}
  const createForm=event.target.closest('[data-form="create-company"]');
  if(createForm&&event.target.closest('[data-wizard-next]')){const step=Number(createForm.dataset.step);if(validateWizardStep(createForm,step))updateWizard(createForm,Math.min(4,step+1));return;}
  if(createForm&&event.target.closest('[data-wizard-back]')){updateWizard(createForm,Math.max(1,Number(createForm.dataset.step)-1));return;}
  const tab=event.target.closest('[data-edit-tab]');if(tab){const edit=tab.closest('[data-form="edit-company"]');if(edit){edit.querySelectorAll('[data-edit-tab]').forEach((x)=>x.classList.toggle('active',x===tab));edit.querySelectorAll('[data-edit-pane]').forEach((x)=>x.hidden=x.dataset.editPane!==tab.dataset.editTab);}return;}
  const moduleToggle=event.target.closest('[data-template-module]');if(moduleToggle){const module=moduleToggle.dataset.templateModule;const form=moduleToggle.closest('form');form.querySelectorAll(`input[name="permission"][data-module="${CSS.escape(module)}"]`).forEach((x)=>x.checked=moduleToggle.checked);updateTemplatePermissionUi(form);return;}
  const actionTarget=event.target.closest('[data-action]');if(!actionTarget)return;
  try{
    if(actionTarget.dataset.action==='template-select-all'){const form=actionTarget.closest('form');form.querySelectorAll('input[name="permission"]').forEach((x)=>x.checked=true);updateTemplatePermissionUi(form);}
    else if(actionTarget.dataset.action==='template-clear-all'){const form=actionTarget.closest('form');form.querySelectorAll('input[name="permission"]').forEach((x)=>x.checked=false);updateTemplatePermissionUi(form);}
    else if(actionTarget.dataset.action==='company-branding'){const c=state.companies.find((x)=>x.company_id===actionTarget.dataset.id);if(c)platformBrandingDialog(c);}
    else if(actionTarget.dataset.action==='company-entitlements'){companyEntitlementsDialog(actionTarget.dataset.id);}
    else if(actionTarget.dataset.action==='company-entitlement-set'){await setCompanyEntitlementFromButton(actionTarget);}
    else if(actionTarget.dataset.action==='company-entitlement-clear'){if(hasPlatformWarning('entitlements','plan_entitlements','company_entitlement_overrides'))throw new Error(L('أعد تحميل بيانات الميزات أولًا.','Reload entitlement data first.'));await api.rpc('clear_company_entitlement_override',{p_company_id:actionTarget.dataset.companyId,p_entitlement_key:actionTarget.dataset.key});await loadData();companyEntitlementsDialog(actionTarget.dataset.companyId);}
    else if(actionTarget.dataset.action==='edit-company'){const c=state.companies.find((x)=>x.company_id===actionTarget.dataset.id);if(c)companyEditDialog(c);}
    else if(actionTarget.dataset.action==='reset-member-password'){const result=await api.invokeFunction('identity-provisioning-v55',{action:'reset_temporary_password',membership_id:actionTarget.dataset.membershipId,password_hours:48});credentialsDialog(result,'member');await loadData();}
  }catch(error){toast('error',L('تعذر تنفيذ العملية','Action failed'),friendlyError(error),7000);}
});
portal.addEventListener('change',(event)=>{if(event.target.matches('[data-plan-select]'))applyPlanDefaults(event.target.form);if(event.target.matches('[data-form="role-template"] input[name="permission"]'))updateTemplatePermissionUi(event.target.closest('form'));});
portal.addEventListener('input',(event)=>{if(event.target.matches('[data-company-name]')){const slug=event.target.form.querySelector('[data-company-slug]');if(slug&&!slug.dataset.touched)slug.value=slugify(event.target.value);}if(event.target.matches('[data-company-slug]'))event.target.dataset.touched='true';});
let companySearchTimer=null;
app.addEventListener('input',(event)=>{if(event.target.matches('[data-company-search]')){state.search=event.target.value;clearTimeout(companySearchTimer);const caret=event.target.selectionStart;companySearchTimer=setTimeout(()=>{render();requestAnimationFrame(()=>{const input=app.querySelector('[data-company-search]');if(input){input.focus();input.setSelectionRange(caret,caret);}});},140);}if(event.target.matches('[data-audit-search]')){state.auditSearch=event.target.value;clearTimeout(companySearchTimer);const caret=event.target.selectionStart;companySearchTimer=setTimeout(()=>{render();requestAnimationFrame(()=>{const input=app.querySelector('[data-audit-search]');if(input){input.focus();input.setSelectionRange(caret,caret);}});},140);}});
app.addEventListener('change',(event)=>{if(event.target.matches('[data-status-filter]')){state.status=event.target.value;render();}else if(event.target.matches('[data-audit-company]')){state.auditCompany=event.target.value;render();}else if(event.target.matches('[data-audit-action]')){state.auditAction=event.target.value;render();}else if(event.target.matches('[data-audit-from]')){state.auditFrom=event.target.value;render();}else if(event.target.matches('[data-audit-to]')){state.auditTo=event.target.value;render();}});

document.addEventListener('submit',async(event)=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const type=form.dataset.form,data=formObject(form);setBusy(form,true);
  try{
    if(type==='login'){await api.signIn({email:data.email,password:data.password});await boot();if(!state.admin&&api.user)toast('error',L('الحساب ليس مسؤول منصة','Not a platform administrator'));}
    else if(type==='create-company'){
      const result=await api.invokeFunction('identity-provisioning-v55',{action:'create_company',password_expiry_hours:Number(data.password_hours||48),company:{name:data.company_name,legal_name:data.legal_name||null,slug:data.slug,short_code:data.short_code||null,official_email:data.official_email||null,phone:data.company_phone||null,whatsapp:data.company_whatsapp||null,country_code:data.country_code||null,city:data.city||null,address:data.address||null,website:data.website||null,industry:data.industry||null,registration_number:data.registration_number||null,tax_number:data.tax_number||null,billing_contact_name:data.billing_contact_name||null,billing_contact_email:data.billing_contact_email||null,billing_contact_phone:data.billing_contact_phone||null,technical_contact_name:data.technical_contact_name||null,technical_contact_email:data.technical_contact_email||null,technical_contact_phone:data.technical_contact_phone||null,internal_notes:data.internal_notes||null,timezone:data.company_timezone||'Africa/Cairo',default_locale:data.default_locale||'ar'},subscription:{plan_code:data.plan_code,status:data.subscription_status,trial_days:Number(data.trial_days||0),max_members:Number(data.max_members||0)||null,max_projects:Number(data.max_projects||0)||null,max_storage_gb:Number(data.max_storage_gb||0)||null,billing_cycle:data.billing_cycle,agreed_price:Number(data.agreed_price||0)||null,currency:data.currency,payment_status:data.payment_status,next_payment_at:data.next_payment_at?new Date(data.next_payment_at).toISOString():null,notes:data.subscription_notes||null},owner:{full_name:data.owner_name,email:data.owner_email,phone:data.owner_phone||null,whatsapp:data.owner_whatsapp||null,job_title:data.owner_job_title||'Company Owner',department:data.owner_department||'Management',employee_code:data.owner_employee_code||null,notes:data.owner_notes||null,timezone:data.company_timezone||'Africa/Cairo',password_hours:Number(data.password_hours||48)}});try{const logoFile=form.querySelector('[name="logo_file"]')?.files?.[0];let logoPath=null;if(logoFile)logoPath=await uploadIdentityImage(logoFile,`${result.company_id}/branding/logo`);await api.rpc('save_company_branding',{p_company_id:result.company_id,p_branding:{app_name:data.company_name,tagline:null,logo_path:logoPath,primary_color:'#4f46e5',accent_color:'#14b8a6',neutral_color:'#64748b',default_theme:'system',sidebar_style:'glass',radius_style:'rounded',density:'comfortable',logo_shape:'rounded'}});}catch(optionalError){result.setup_warning=friendlyError(optionalError);}closeDialog();try{await loadData();}catch(refreshError){result.setup_warning=[result.setup_warning,friendlyError(refreshError)].filter(Boolean).join(' — ');}render();credentialsDialog(result,'company');
    }
    else if(type==='platform-branding'){const c=state.companies.find((x)=>x.company_id===form.dataset.companyId);const logoFile=form.querySelector('[name="logo_file"]')?.files?.[0];let logoPath=c?.branding_logo_path||null;if(logoFile)logoPath=await uploadIdentityImage(logoFile,`${form.dataset.companyId}/branding/logo`);await api.rpc('save_company_branding',{p_company_id:form.dataset.companyId,p_branding:{app_name:data.app_name||c?.company_name,tagline:data.tagline||null,logo_path:logoPath,primary_color:data.primary_color||'#4f46e5',accent_color:data.accent_color||'#14b8a6',neutral_color:'#64748b',default_theme:data.default_theme||'system',sidebar_style:data.sidebar_style||'glass',radius_style:'rounded',density:'comfortable',logo_shape:'rounded'}});closeDialog();await loadData();render();toast('success',L('تم تحديث هوية الشركة','Company identity updated'));}
    else if(type==='role-template'){if(hasPlatformWarning('permissions','role_templates','role_template_permissions'))throw new Error(L('أعد تحميل مكتبة الصلاحيات أولًا.','Reload the permission library first.'));const permissions=selectedTemplatePermissionKeys(form);if(!permissions.length)throw new Error(L('اختر صلاحية واحدة على الأقل قبل الحفظ.','Select at least one permission before saving.'));const saved=await api.rpc('platform_save_role_template_definition',{p_payload:{template_id:form.dataset.templateId||null,code:data.code,name_ar:data.name_ar,name_en:data.name_en,description_ar:data.description_ar||null,description_en:data.description_en||null,color:data.color||'#4f46e5',icon:data.icon||'shield',category:data.category||'general',is_active:form.querySelector('[name="is_active"]')?.checked!==false,is_recommended:Boolean(form.querySelector('[name="is_recommended"]')?.checked),permission_keys:permissions}});if(Number(saved?.permission_count)!==permissions.length)throw new Error(L('لم يؤكد الخادم حفظ جميع الصلاحيات.','The server did not confirm every selected permission.'));closeDialog();await loadData();render();toast('success',L(`تم حفظ القالب مع ${permissions.length} صلاحية`,`Template saved with ${permissions.length} permissions`));}
    else if(type==='edit-company'){
      await api.invokeFunction('identity-provisioning-v55',{action:'update_company',company_id:form.dataset.id,company:{name:data.name,legal_name:data.legal_name||null,short_code:data.short_code||null,official_email:data.official_email||null,phone:data.phone||null,whatsapp:data.whatsapp||null,city:data.city||null,industry:data.industry||null,website:data.website||null,registration_number:data.registration_number||null,tax_number:data.tax_number||null,billing_contact_name:data.billing_contact_name||null,billing_contact_email:data.billing_contact_email||null,billing_contact_phone:data.billing_contact_phone||null,technical_contact_name:data.technical_contact_name||null,technical_contact_email:data.technical_contact_email||null,technical_contact_phone:data.technical_contact_phone||null,onboarding_status:data.onboarding_status,internal_notes:data.internal_notes||null},subscription:{plan_id:data.plan_id,status:data.status,payment_status:data.payment_status,max_members:Number(data.max_members||0)||null,max_projects:Number(data.max_projects||0)||null,max_storage_gb:Number(data.max_storage_gb||0)||null,billing_cycle:data.billing_cycle,agreed_price:Number(data.agreed_price||0)||null,currency:data.currency,trial_ends_at:data.trial_ends_at?new Date(data.trial_ends_at).toISOString():null,current_period_ends_at:data.current_period_ends_at?new Date(data.current_period_ends_at).toISOString():null,next_payment_at:data.next_payment_at?new Date(data.next_payment_at).toISOString():null}});closeDialog();await loadData();render();toast('success',L('تم حفظ بيانات الشركة','Company updated'));
    }
  }catch(error){toast('error',L('تعذر حفظ البيانات','Could not save'),friendlyError(error),7000);}
  finally{if(document.contains(form))setBusy(form,false);}
});
